solution.solution.py:
def to_hex_colour(r, g, b):
    return f"#{r:02X}{g:02X}{b:02X}"

def from_hex_colour(text):
    return (int(text[1:3], 16), int(text[3:5], 16), int(text[5:7], 16))

def grey(r, g, b):
    return round(0.299 * r + 0.587 * g + 0.114 * b)

def image_bytes(width, height, bytes_per_pixel):
    return width * height * bytes_per_pixel

unitTests:
@test("to hex")
def _():
    check_eq(to_hex_colour(255, 136, 0), "#FF8800")
    check_eq(to_hex_colour(0, 0, 0), "#000000")
    check_eq(to_hex_colour(255, 255, 255), "#FFFFFF")
    check_eq(to_hex_colour(10, 11, 12), "#0A0B0C")

@test("from hex")
def _():
    check_eq(from_hex_colour("#ff8800"), (255, 136, 0))
    check_eq(from_hex_colour("#0A0B0C"), (10, 11, 12))

@test("brightness")
def _():
    check_eq(grey(255, 255, 255), 255)
    check_eq(grey(0, 0, 0), 0)
    check_eq(grey(255, 0, 0), 76)
    check_eq(grey(0, 255, 0), 150)
    check_eq(grey(0, 0, 255), 29)

@test("image sizes")
def _():
    check_eq(image_bytes(1920, 1080, 3), 6220800)
    check_eq(image_bytes(100, 100, 4), 40000)

